const partOf = (n) => {
  if (n <= 7) return `Part 1 · Chapter ${n}`;
  if (n <= 14) return `Part 2 · Chapter ${n - 7}`;
  if (n <= 20) return `Part 3 · Chapter ${n - 14}`;
  if (n <= 26) return `Part 4 · Chapter ${n - 20}`;
  if (n <= 31) return `Part 5 · Chapter ${n - 26}`;
  if (n <= 39) return `Part 6 · Chapter ${n - 31}`;
  return `Epilogue · Chapter ${n - 39}`;
};

